import * as fs from 'fs';

function formatNumberWithCommas(n: number, decimals: number = 0): string {
    const fixed = n.toFixed(decimals);
    const negative = fixed.startsWith('-');
    const abs = negative ? fixed.slice(1) : fixed;
    const parts = abs.split('.');
    const intPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    const result = (negative ? '-' : '') + intPart + (parts.length > 1 ? '.' + parts[1] : '');
    return result;
}

function parseCsvLine(line: string): string[] {
    const fields: string[] = [];
    let current = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
        const ch = line[i];
        if (inQuotes) {
            if (ch === '"') {
                if (i + 1 < line.length && line[i + 1] === '"') {
                    current += '"';
                    i++;
                } else {
                    inQuotes = false;
                }
            } else {
                current += ch;
            }
        } else {
            if (ch === '"') {
                inQuotes = true;
            } else if (ch === ',') {
                fields.push(current);
                current = '';
            } else {
                current += ch;
            }
        }
    }
    fields.push(current);
    return fields;
}

