import json
import heapq

def main():
    with open("<tmp>") as f:
        data = json.load(f)

    nodes = data["nodes"]
    edges = data["edges"]

    adj = {node: [] for node in nodes}
    for e in edges:
        adj[e["from"]].append((e["to"], e["weight"]))
        adj[e["to"]].append((e["from"], e["weight"]))

    INF = float('inf')
    dist = {node: INF for node in nodes}
    dist["A"] = 0

    heap = [(0, "A")]
    visited = set()

    while heap:
        d, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        for v, w in adj[u]:
            if v not in visited and d + w < dist[v]:
                dist[v] = d + w
                heapq.heappush(heap, (dist[v], v))

    print("=== Shortest Paths from A ===")
    print()
    for node in sorted(nodes):
        d = dist[node]
        if d == INF:
            print(f"A -> {node}: unreachable")
        elif d == int(d):
            print(f"A -> {node}: {int(d)}")
        else:
            print(f"A -> {node}: {d}")

main()

