        if (idx >= obj.length() || obj.charAt(idx) != '"') return null;
        idx++;
        int e = idx;
        while (e < obj.length() && obj.charAt(e) != '"') {
            if (obj.charAt(e) == '\\' && e + 1 < obj.length()) e++;
            e++;
        }
        return obj.substring(idx, e);
    }

    static String extractNumber(String obj, String key) {
        String search = "\"" + key + "\"";
        int idx = obj.indexOf(search);
        if (idx == -1) return null;
        idx += search.length();
        while (idx < obj.length() && obj.charAt(idx) != ':') idx++;
        idx++;
