use std::collections::HashMap;
use std::fs;

fn format_commas(n: u64) -> String {
    let s = n.to_string();
    let len = s.len();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read CSV file");

    let lines: Vec<&str> = content.lines().collect();

    let mut dept_data: HashMap<String, (f64, u64)> = HashMap::new();
    let mut highest_name = String::new();
    let mut highest_salary: f64 = 0.0;
    let mut total_budget: f64 = 0.0;

    for line in lines.iter().skip(1) {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let fields: Vec<&str> = trimmed.split(',').map(|s| s.trim()).collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].to_string();
        let department = fields[2].to_string();
        let salary: f64 = fields[3].parse().unwrap_or(0.0);

        let entry = dept_data.entry(department.clone()).or_insert((0.0, 0));
        entry.0 += salary;
        entry.1 += 1;

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }

        total_budget += salary;
    }

    let mut depts: Vec<&String> = dept_data.keys().collect();
    depts.sort();

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for dept in &depts {
        let (total, count) = &dept_data[dept];
        let avg = total / *count as f64;
        let int_part = avg as u64;
        let dec_part = ((avg * 100.0).round() as u64) % 100;
        println!("  {}: ${}.{:02}", dept, format_commas(int_part), dec_part);
    }
    println!();
    println!("Highest Paid: {} (${})", highest_name, format_commas(highest_salary as u64));
    println!();
    println!("Departments with >2 employees:");
    for dept in &depts {
        let (_, count) = &dept_data[dept];
        if *count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    println!("Total Budget: ${}", format_commas(total_budget as u64));
}

