#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

typedef struct {
    int id;
    char name[512];
    double price;
    char category[512];
    int stock;
} Product;

static int compare_products(const void *a, const void *b) {
    const Product *pa = (const Product *)a;
    const Product *pb = (const Product *)b;
    return strcmp(pa->name, pb->name);
}

static void skip_whitespace(const char **s) {
    while (**s == ' ' || **s == '\t' || **s == '\n' || **s == '\r') (*s)++;
}

static void parse_string(const char **s, char *out, size_t out_size) {
    if (**s != '"') { out[0] = '\0'; return; }
    (*s)++;
    size_t i = 0;
    while (**s != '\0' && **s != '"') {
        if (**s == '\\' && i + 1 < out_size) {
            (*s)++;
            switch (**s) {
                case 'n': out[i++] = '\n'; break;
                case 't': out[i++] = '\t'; break;
                case 'r': out[i++] = '\r'; break;
                case '"': out[i++] = '"'; break;
                case '\\': out[i++] = '\\'; break;
                case '/': out[i++] = '/'; break;
                case 'b': out[i++] = '\b'; break;
                case 'f': out[i++] = '\f'; break;
                case 'u':
                    /* skip 4 hex digits, put '?' */
                    for (int k = 0; k < 4 && *(*s + 1) != '\0'; k++) (*s)++;
                    out[i++] = '?';
                    break;
                default: out[i++] = **s; break;
            }
        } else if (i + 1 < out_size) {
            out[i++] = **s;
            (*s)++;
        } else {
            (*s)++;
        }
    }
    if (**s == '"') (*s)++;
    out[i] = '\0';
}

static double parse_number(const char **s) {
    skip_whitespace(s);
    char *end;
    double val = strtod(*s, &end);
    *s = end;
    return val;
}

static long parse_int(const char **s) {
    skip_whitespace(s);
    char *end;
    long val = strtol(*s, &end, 10);
    *s = end;
    return val;
}

static void parse_product(const char **s, Product *p) {
    /* expect { */
    skip_whitespace(s);
    if (**s != '{') return;
    (*s)++;
    skip_whitespace(s);

    p->id = 0;
    p->name[0] = '\0';
    p->price = 0.0;
    p->category[0] = '\0';
    p->stock = 0;

    while (**s != '\0' && **s != '}') {
        skip_whitespace(s);
        if (**s == '}') break;
        if (**s == ',') { (*s)++; continue; }
        if (**s != '"') { (*s)++; continue; }

        char key[256];
        parse_string(s, key, sizeof(key));
        skip_whitespace(s);
        if (**s == ':') (*s)++;
        skip_whitespace(s);

        if (strcmp(key, "id") == 0) {
            p->id = (int)parse_int(s);
        } else if (strcmp(key, "name") == 0) {
            parse_string(s, p->name, sizeof(p->name));
        } else if (strcmp(key, "price") == 0) {
            p->price = parse_number(s);
        } else if (strcmp(key, "category") == 0) {
            parse_string(s, p->category, sizeof(p->category));
        } else if (strcmp(key, "stock") == 0) {
            p->stock = (int)parse_int(s);
        } else {
            /* skip unknown value */
            if (**s == '"') {
                char dummy[1024];
                parse_string(s, dummy, sizeof(dummy));
            } else if (**s == '{' || **s == '[') {
                int depth = 0;
                while (**s != '\0') {
                    if (**s == '{' || **s == '[') depth++;
                    else if (**s == '}' || **s == ']') { depth--; if (depth == 0) { (*s)++; break; } }
                    else if (**s == '"') {
                        (*s)++;
                        while (**s != '\0' && **s != '"') { if (**s == '\\') (*s)++; (*s)++; }
                        if (**s == '"') (*s)++;
                    } else {
                        (*s)++;
                    }
