static void parse_string(const char **s, char *out, size_t out_size) {
    if (**s != '"') { out[0] = '\0'; return; }
    (*s)++;
    size_t i = 0;
    while (**s != '\0' && **s != '"') {
        if (**s == '\\' && i + 1 < out_size) {
            (*s)++;
            switch (**s) {
                case 'n': out[i++] = '\n'; break;
                case 't': out[i++] = '\t'; break;
                case 'r': out[i++] = '\r'; break;
                case '"': out[i++] = '"'; break;
                case '\\': out[i++] = '\\'; break;
                case '/': out[i++] = '/'; break;
                case 'b': out[i++] = '\b'; break;
                case 'f': out[i++] = '\f'; break;
                case 'u':
                    /* skip 4 hex digits, put '?' */
                    for (int k = 0; k < 4 && *(*s + 1) != '\0'; k++) (*s)++;
                    out[i++] = '?';
                    break;
                default: out[i++] = **s; break;
            }
        } else if (i + 1 < out_size) {
            out[i++] = **s;
            (*s)++;
        } else {
            (*s)++;
        }
    }
    if (**s == '"') (*s)++;
    out[i] = '\0';
}

