                    } else {
                        (*s)++;
                    }
                }
            } else {
                while (**s != '\0' && **s != ',' && **s != '}' && **s != ']') (*s)++;
            }
        }
        skip_whitespace(s);
    }
    if (**s == '}') (*s)++;
