                    /* encode as UTF-8 */
                    if (code < 0x80) {
                        if (n+1>=cap){cap*=2;s=realloc(s,cap);} s[n++]=(char)code;
                    } else if (code < 0x800) {
                        if (n+3>=cap){cap*=2;s=realloc(s,cap);}
                        s[n++]=(char)(0xC0|(code>>6));
                        s[n++]=(char)(0x80|(code&0x3F));
                    } else {
                        if (n+3>=cap){cap*=2;s=realloc(s,cap);}
                        s[n++]=(char)(0xE0|(code>>12));
                        s[n++]=(char)(0x80|((code>>6)&0x3F));
                        s[n++]=(char)(0x80|(code&0x3F));
                    }
                    break;
                }
                default: if (n+1>=cap){cap*=2;s=realloc(s,cap);} s[n++]=e; break;
            }
            p->pos++;
        } else {
            if (n+1>=cap){cap*=2;s=realloc(s,cap);}
            s[n++]=c;
            p->pos++;
        }
    }
    if (p->pos < p->len) p->pos++; /* skip closing quote */
    if (n+1>=cap){cap*=2;s=realloc(s,cap);}
    s[n]='\0';
    return s;
}

static JsonValue *parse_value(Parser *p);

static JsonValue *parse_number(Parser *p) {
    int start = p->pos;
    while (p->pos < p->len) {
        char c = p->buf[p->pos];
        if ((c>='0'&&c<='9')||c=='-'||c=='+'||c=='.'||c=='e'||c=='E') p->pos++;
        else break;
    }
    int len = p->pos - start;
    char *numstr = (char *)malloc(len + 1);
    memcpy(numstr, p->buf + start, len);
    numstr[len] = '\0';
    JsonValue *v = json_new();
    v->type = JSON_NUMBER;
    v->num_val = atof(numstr);
    v->num_str = numstr;
    return v;
}

static JsonValue *parse_array(Parser *p) {
    p->pos++; /* skip [ */
    JsonValue *arr = json_new();
    arr->type = JSON_ARRAY;
    skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == ']') {
        p->pos++;
        return arr;
    }
    while (1) {
        skip_ws(p);
        JsonValue *item = parse_value(p);
        array_push(arr, item);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->buf[p->pos] == ']') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return arr;
}

static JsonValue *parse_object(Parser *p) {
    p->pos++; /* skip { */
    JsonValue *obj = json_new();
    obj->type = JSON_OBJECT;
    skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == '}') {
        p->pos++;
        return obj;
    }
    while (1) {
        skip_ws(p);
        char *key = parse_string_raw(p);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ':') p->pos++;
        skip_ws(p);
        JsonValue *val = parse_value(p);
        object_add(obj, key, val);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->buf[p->pos] == '}') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return obj;
}

static JsonValue *parse_value(Parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) {
        JsonValue *v = json_new();
        v->type = JSON_NULL;
        return v;
    }
    char c = p->buf[p->pos];
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == '"') {
        JsonValue *v = json_new();
        v->type = JSON_STRING;
        v->str_val = parse_string_raw(p);
        return v;
    }
    if (c == 't' && p->pos + 4 <= p->len && strncmp(p->buf+p->pos,"true",4)==0) {
        p->pos += 4;
        JsonValue *v = json_new();
        v->type = JSON_BOOL;
        v->bool_val = 1;
        return v;
    }
    if (c == 'f' && p->pos + 5 <= p->len && strncmp(p->buf+p->pos,"false",5)==0) {
        p->pos += 5;
        JsonValue *v = json_new();
        v->type = JSON_BOOL;
        v->bool_val = 0;
        return v;
    }
    if (c == 'n' && p->pos + 4 <= p->len && strncmp(p->buf+p->pos,"null",4)==0) {
        p->pos += 4;
        JsonValue *v = json_new();
        v->type = JSON_NULL;
        return v;
    }
    if (c == '-' || (c >= '0' && c <= '9')) return parse_number(p);
    /* fallback: null */
    JsonValue *v = json_new();
    v->type = JSON_NULL;
    return v;
}

static JsonValue *parse_json(const char *buf, int len) {
    Parser p = { buf, 0, len };
    return parse_value(&p);
}

/* Deep equality */
static int json_equal(const JsonValue *a, const JsonValue *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->bool_val == b->bool_val;
        case JSON_NUMBER: return a->num_val == b->num_val;
        case JSON_STRING: return strcmp(a->str_val, b->str_val) == 0;
        case JSON_ARRAY:
            if (a->item_count != b->item_count) return 0;
            for (int i = 0; i < a->item_count; i++)
                if (!json_equal(a->items[i], b->items[i])) return 0;
            return 1;
        case JSON_OBJECT:
            if (a->pair_count != b->pair_count) return 0;
            for (int i = 0; i < a->pair_count; i++) {
                int found = 0;
                for (int j = 0; j < b->pair_count; j++) {
                    if (strcmp(a->keys[i], b->keys[j]) == 0) {
                        if (!json_equal(a->values[i], b->values[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

/* Deep clone */
static JsonValue *json_clone(const JsonValue *src) {
    JsonValue *v = json_new();
    v->type = src->type;
    switch (src->type) {
        case JSON_NULL: break;
        case JSON_BOOL: v->bool_val = src->bool_val; break;
        case JSON_NUMBER:
            v->num_val = src->num_val;
            v->num_str = strdup(src->num_str);
            break;
        case JSON_STRING:
            v->str_val = strdup(src->str_val);
            break;
        case JSON_ARRAY:
            v->item_cap = src->item_count;
            v->items = (JsonValue **)calloc(src->item_count, sizeof(JsonValue *));
            for (int i = 0; i < src->item_count; i++)
                v->items[i] = json_clone(src->items[i]);
            v->item_count = src->item_count;
            break;
        case JSON_OBJECT:
            v->pair_cap = src->pair_count;
            v->keys = (char **)calloc(src->pair_count, sizeof(char *));
            v->values = (JsonValue **)calloc(src->pair_count, sizeof(JsonValue *));
            for (int i = 0; i < src->pair_count; i++) {
                v->keys[i] = strdup(src->keys[i]);
                v->values[i] = json_clone(src->values[i]);
            }
            v->pair_count = src->pair_count;
            break;
    }
    return v;
}

/* Merge: result is a new JsonValue */
static JsonValue *json_merge(const JsonValue *a, const JsonValue *b) {
    /* Both objects: merge recursively */
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *result = json_new();
        result->type = JSON_OBJECT;
        /* Start with all of A's keys */
        for (int i = 0; i < a->pair_count; i++) {
            object_add(result, strdup(a->keys[i]), json_clone(a->values[i]));
        }
        /* For each key in B: if exists in result, merge; else add */
        for (int i = 0; i < b->pair_count; i++) {
            int found = -1;
            for (int j = 0; j < result->pair_count; j++) {
                if (strcmp(result->keys[j], b->keys[i]) == 0) {
                    found = j;
                    break;
                }
            }
            if (found >= 0) {
                JsonValue *merged = json_merge(result->values[found], b->values[i]);
                json_free(result->values[found]);
                result->values[found] = merged;
            } else {
                object_add(result, strdup(b->keys[i]), json_clone(b->values[i]));
            }
        }
        return result;
    }
    /* Both arrays: concatenate, dedup (A first, then new from B) */
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JsonValue *result = json_new();
        result->type = JSON_ARRAY;
        /* Add all A items */
        for (int i = 0; i < a->item_count; i++) {
            array_push(result, json_clone(a->items[i]));
        }
        /* Add B items that are not already present */
        for (int i = 0; i < b->item_count; i++) {
            int dup = 0;
            for (int j = 0; j < result->item_count; j++) {
                if (json_equal(result->items[j], b->items[i])) {
                    dup = 1;
                    break;
                }
            }
            if (!dup) {
                array_push(result, json_clone(b->items[i]));
            }
        }
        return result;
    }
    /* Scalar conflict or type mismatch: B overrides A */
    return json_clone(b);
}

/* Sort object keys (and recursively sort nested objects) */
static int cmp_keys(const void *a, const void *b) {
    const char *ka = *(const char **)a;
    const char *kb = *(const char **)b;
    return strcmp(ka, kb);
}

static void sort_object(JsonValue *obj) {
    if (obj->type != JSON_OBJECT) return;
    /* Sort pairs by key using insertion sort to keep keys and values in sync */
    for (int i = 1; i < obj->pair_count; i++) {
        char *k = obj->keys[i];
        JsonValue *v = obj->values[i];
        int j = i - 1;
        while (j >= 0 && strcmp(obj->keys[j], k) > 0) {
            obj->keys[j+1] = obj->keys[j];
            obj->values[j+1] = obj->values[j];
            j--;
        }
        obj->keys[j+1] = k;
        obj->values[j+1] = v;
    }
    /* Recursively sort nested objects */
    for (int i = 0; i < obj->pair_count; i++) {
        sort_object(obj->values[i]);
    }
}

/* Pretty print */
static void print_string_escaped(const char *s) {
    fputc('"', stdout);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", stdout); break;
            case '\\': fputs("\\\\", stdout); break;
            case '\b': fputs("\\b", stdout); break;
            case '\f': fputs("\\f", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default:
                if (c < 0x20) {
                    printf("\\u%04x", c);
                } else {
                    fputc(c, stdout);
                }
        }
    }
    fputc('"', stdout);
}

static void print_value(const JsonValue *v, int indent) {
    switch (v->type) {
        case JSON_NULL:
            fputs("null", stdout);
            break;
        case JSON_BOOL:
            fputs(v->bool_val ? "true" : "false", stdout);
            break;
        case JSON_NUMBER:
            fputs(v->num_str, stdout);
            break;
        case JSON_STRING:
            print_string_escaped(v->str_val);
            break;
        case JSON_ARRAY:
            if (v->item_count == 0) {
                fputs("[]", stdout);
                return;
            }
            fputc('[', stdout);
            for (int i = 0; i < v->item_count; i++) {
                fputc('\n', stdout);
                for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', stdout);
                print_value(v->items[i], indent + 1);
                if (i < v->item_count - 1) fputc(',', stdout);
            }
            fputc('\n', stdout);
            for (int s = 0; s < indent * 2; s++) fputc(' ', stdout);
            fputc(']', stdout);
            break;
        case JSON_OBJECT:
            if (v->pair_count == 0) {
                fputs("{}", stdout);
                return;
            }
            fputc('{', stdout);
            for (int i = 0; i < v->pair_count; i++) {
                fputc('\n', stdout);
                for (int s = 0; s < (indent + 1) * 2; s++) fputc(' ', stdout);
                print_string_escaped(v->keys[i]);
                fputs(": ", stdout);
                print_value(v->values[i], indent + 1);
                if (i < v->pair_count - 1) fputc(',', stdout);
            }
            fputc('\n', stdout);
            for (int s = 0; s < indent * 2; s++) fputc(' ', stdout);
            fputc('}', stdout);
            break;
    }
}

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(sz + 1);
    size_t rd = fread(buf, 1, sz, f);
    fclose(f);
    buf[rd] = '\0';
    *out_len = (int)rd;
    return buf;
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    size_t len_a, len_b;
    char *buf_a = read_file(path_a, &len_a);
    char *buf_b = read_file(path_b, &len_b);
    if (!buf_a || !buf_b) {
        fprintf(stderr, "Error reading input files\n");
        return 1;
    }

    JsonValue *a = parse_json(buf_a, (int)len_a);
    JsonValue *b = parse_json(buf_b, (int)len_b);

    JsonValue *merged = json_merge(a, b);

    sort_object(merged);

    print_value(merged, 0);
    fputc('\n', stdout);

    json_free(a);
    json_free(b);
    json_free(merged);
    free(buf_a);
    free(buf_b);
    return 0;
}
