        }

        Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++;
            skipWhitespace();
            if (input.charAt(pos) == '}') { pos++; return map; }
            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                if (input.charAt(pos) != ':') throw new RuntimeException("Expected ':' at pos " + pos);
                pos++;
                skipWhitespace();
                Object value = parseValue();
                map.put(key, value);
                skipWhitespace();
                if (input.charAt(pos) == ',') {
                    pos++;
                } else if (input.charAt(pos) == '}') {
                    pos++;
                    break;
                } else {
                    throw new RuntimeException("Expected ',' or '}' at pos " + pos);
                }
            }
            return map;
        }

        List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++;
            skipWhitespace();
            if (input.charAt(pos) == ']') { pos++; return list; }
            while (true) {
                skipWhitespace();
                Object value = parseValue();
                list.add(value);
                skipWhitespace();
                if (input.charAt(pos) == ',') {
                    pos++;
                } else if (input.charAt(pos) == ']') {
                    pos++;
                    break;
                } else {
                    throw new RuntimeException("Expected ',' or ']' at pos " + pos);
                }
            }
            return list;
        }

        String parseString() {
            if (input.charAt(pos) != '"') throw new RuntimeException("Expected string at pos " + pos);
            pos++;
            StringBuilder sb = new StringBuilder();
            while (true) {
                char c = input.charAt(pos);
                if (c == '"') { pos++; break; }
                if (c == '\\') {
                    pos++;
                    char esc = input.charAt(pos);
                    switch (esc) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            String hex = input.substring(pos + 1, pos + 5);
                            sb.append((char) Integer.parseInt(hex, 16));
                            pos += 4;
                            break;
                        default: throw new RuntimeException("Invalid escape at pos " + pos);
                    }
                    pos++;
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            return sb.toString();
        }

        Object parseNumber() {
            int start = pos;
            boolean isDouble = false;
            if (pos < input.length() && input.charAt(pos) == '-') pos++;
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c >= '0' && c <= '9') { pos++; }
                else if (c == '.' || c == 'e' || c == 'E') { isDouble = true; pos++; }
                else if (c == '+' || c == '-') { pos++; }
                else break;
            }
            String numStr = input.substring(start, pos);
            if (isDouble) return Double.parseDouble(numStr);
            return Long.parseLong(numStr);
        }
    }

    static Object deepMerge(Object a, Object b) {
        if (a instanceof Map && b instanceof Map) {
            Map<String, Object> result = new LinkedHashMap<>();
            @SuppressWarnings("unchecked")
            Map<String, Object> mapA = (Map<String, Object>) a;
            @SuppressWarnings("unchecked")
            Map<String, Object> mapB = (Map<String, Object>) b;
            for (Map.Entry<String, Object> entry : mapA.entrySet()) {
                result.put(entry.getKey(), entry.getValue());
            }
            for (Map.Entry<String, Object> entry : mapB.entrySet()) {
                String key = entry.getKey();
                if (result.containsKey(key)) {
                    result.put(key, deepMerge(result.get(key), entry.getValue()));
                } else {
                    result.put(key, entry.getValue());
                }
            }
            return result;
        }
        if (a instanceof List && b instanceof List) {
            List<Object> result = new ArrayList<>((List<?>) a);
            for (Object item : (List<?>) b) {
                if (!result.contains(item)) {
                    result.add(item);
                }
            }
            return result;
        }
        return b;
    }

    static String prettyPrint(Object obj, int indent) {
        if (obj == null) return "null";
        if (obj instanceof Boolean) return obj.toString();
        if (obj instanceof String) return escapeString((String) obj);
        if (obj instanceof Long) return obj.toString();
        if (obj instanceof Double) {
            double d = (Double) obj;
            if (d == Math.floor(d) && !Double.isInfinite(d) && !Double.isNaN(d) && Math.abs(d) < 1e15) {
                return String.valueOf((long) d) + ".0";
            }
            return String.valueOf(d);
        }
        if (obj instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> map = (Map<String, Object>) obj;
            if (map.isEmpty()) return "{}";
            List<String> keys = new ArrayList<>(map.keySet());
            Collections.sort(keys);
            String padding = "  ".repeat(indent);
            String inner = "  ".repeat(indent + 1);
            StringBuilder sb = new StringBuilder();
            sb.append("{\n");
            for (int i = 0; i < keys.size(); i++) {
                sb.append(inner);
                sb.append(escapeString(keys.get(i)));
                sb.append(": ");
                sb.append(prettyPrint(map.get(keys.get(i)), indent + 1));
                if (i < keys.size() - 1) sb.append(",");
                sb.append("\n");
            }
            sb.append(padding).append("}");
            return sb.toString();
        }
        if (obj instanceof List) {
            List<?> list = (List<?>) obj;
            if (list.isEmpty()) return "[]";
            String padding = "  ".repeat(indent);
            String inner = "  ".repeat(indent + 1);
            StringBuilder sb = new StringBuilder();
            sb.append("[\n");
            for (int i = 0; i < list.size(); i++) {
                sb.append(inner);
                sb.append(prettyPrint(list.get(i), indent + 1));
                if (i < list.size() - 1) sb.append(",");
                sb.append("\n");
            }
            sb.append(padding).append("]");
            return sb.toString();
        }
        return obj.toString();
    }

    static String escapeString(String s) {
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        sb.append("\"");
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        String pathA = "<tmp>";
        String pathB = "<tmp>";

        String jsonA = new String(Files.readAllBytes(Paths.get(pathA)), "UTF-8");
        String jsonB = new String(Files.readAllBytes(Paths.get(pathB)), "UTF-8");

        Object objA = new Parser(jsonA).parse();
        Object objB = new Parser(jsonB).parse();

        Object merged = deepMerge(objA, objB);

        System.out.println(prettyPrint(merged, 0));
    }
}
