#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>

typedef struct {
    char *name;
    char *department;
    double salary;
} Employee;

typedef struct {
    char *name;
    double total;
    int count;
} Dept;

static void format_comma_long(long val, char *buf, size_t bufsz) {
    int neg = 0;
    if (val < 0) { neg = 1; val = -val; }

    char tmp[32];
    int len = 0;
    if (val == 0) {
        tmp[len++] = '0';
    } else {
        char rev[32];
        int rlen = 0;
        while (val > 0) {
            rev[rlen++] = (char)('0' + (val % 10));
            val /= 10;
        }
        for (int i = 0; i < rlen; i++) tmp[len++] = rev[rlen - 1 - i];
    }

    int outlen = 0;
    if (neg) buf[outlen++] = '-';
    for (int i = 0; i < len; i++) {
        if (i > 0 && (len - i) % 3 == 0) {
            if (outlen + 2 < (int)bufsz) buf[outlen++] = ',';
        }
        if (outlen + 1 < (int)bufsz) buf[outlen++] = tmp[i];
    }
    buf[outlen] = '\0';
}

static void format_comma_double(double val, char *buf, size_t bufsz) {
    int neg = 0;
    if (val < 0) { neg = 1; val = -val; }

    long intpart = (long)val;
    long decpart = (long)((val - (double)intpart) * 100.0 + 0.5);
    if (decpart >= 100) { intpart += decpart / 100; decpart %= 100; }

    char intbuf[64];
    format_comma_long(intpart, intbuf, sizeof(intbuf));

    if (neg) {
        snprintf(buf, bufsz, "-%s.%02ld", intbuf, decpart);
    } else {
        snprintf(buf, bufsz, "%s.%02ld", intbuf, decpart);
    }
}

static int compare_depts(const void *a, const void *b) {
    const Dept *da = *(const Dept * const *)a;
    const Dept *db = *(const Dept * const *)b;
    return strcmp(da->name, db->name);
}

int main(void) {
    const char *filename = "<tmp>";

    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s\n", filename);
        return 1;
    }

    /* Skip header line */
    char hbuf[512];
    if (fgets(hbuf, sizeof(hbuf), fp) == NULL) {
        fclose(fp);
        fprintf(stderr, "Error: empty file\n");
        return 1;
    }

    /* Read all data lines */
    char *line = NULL;
    size_t linecap = 0;
    ssize_t linelen;

    char **lines = NULL;
    size_t nlines = 0, linescap = 0;

    while ((linelen = getline(&line, &linecap, fp)) != -1) {
        /* strip trailing newline / carriage return */
        while (linelen > 0 && (line[linelen - 1] == '\n' || line[linelen - 1] == '\r')) {
            line[--linelen] = '\0';
        }
        if (linelen == 0) continue;

        if (nlines == linescap) {
            linescap = linescap ? linescap * 2 : 128;
            lines = (char **)realloc(lines, linescap * sizeof(char *));
            if (!lines) { fclose(fp); return 1; }
        }
        lines[nlines] = (char *)malloc((size_t)linelen + 1);
        if (!lines[nlines]) { fclose(fp); return 1; }
        memcpy(lines[nlines], line, (size_t)linelen + 1);
        nlines++;
    }

    free(line);
    fclose(fp);

    /* Parse employees */
    Employee *emps = (Employee *)malloc(nlines * sizeof(Employee));
    if (!emps && nlines > 0) return 1;
    size_t nemps = 0;

    for (size_t i = 0; i < nlines; i++) {
        char *csv = lines[i];
        char *fields[6] = {0};
        int nf = 0;
        char *p = csv;
        while (nf < 6) {
            fields[nf++] = p;
            p = strchr(p, ',');
            if (p) { *p = '\0'; p++; }
            else break;
        }
        if (nf < 4) continue;

        emps[nemps].name = strdup(fields[1]);
        emps[nemps].department = strdup(fields[2]);
        emps[nemps].salary = atof(fields[3]);
        nemps++;
    }

    /* Collect unique departments */
    char **dept_names = NULL;
    double *dept_totals = NULL;
    int *dept_counts = NULL;
    size_t ndepts = 0, deptscap = 0;

    for (size_t i = 0; i < nemps; i++) {
        int found = 0;
        for (size_t j = 0; j < ndepts; j++) {
            if (strcmp(dept_names[j], emps[i].department) == 0) {
                dept_totals[j] += emps[i].salary;
                dept_counts[j]++;
                found = 1;
                break;
            }
        }
        if (!found) {
            if (ndepts == deptscap) {
                deptscap = deptscap ? deptscap * 2 : 16;
                dept_names = (char **)realloc(dept_names, deptscap * sizeof(char *));
                dept_totals = (double *)realloc(dept_totals, deptscap * sizeof(double));
                dept_counts = (int *)realloc(dept_counts, deptscap * sizeof(int));
            }
            dept_names[ndepts] = strdup(emps[i].department);
            dept_totals[ndepts] = emps[i].salary;
            dept_counts[ndepts] = 1;
            ndepts++;
        }
    }

    /* Build Dept array and sort alphabetically */
    Dept *depts = (Dept *)malloc(ndepts * sizeof(Dept));
    for (size_t i = 0; i < ndepts; i++) {
        depts[i].name = dept_names[i];
        depts[i].total = dept_totals[i];
        depts[i].count = dept_counts[i];
    }

    Dept **dept_ptrs = (Dept **)malloc(ndepts * sizeof(Dept *));
    for (size_t i = 0; i < ndepts; i++) dept_ptrs[i] = &depts[i];
    qsort(dept_ptrs, ndepts, sizeof(Dept *), compare_depts);

    /* Highest paid */
    int max_idx = 0;
    for (size_t i = 1; i < nemps; i++) {
        if (emps[i].salary > emps[max_idx].salary) max_idx = (int)i;
    }

    /* Total budget */
    double total_budget = 0.0;
    for (size_t i = 0; i < nemps; i++) total_budget += emps[i].salary;

    /* Output */
    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (size_t i = 0; i < ndepts; i++) {
        double avg = dept_ptrs[i]->total / (double)dept_ptrs[i]->count;
        char buf[64];
        format_comma_double(avg, buf, sizeof(buf));
        printf("  %s: $%s\n", dept_ptrs[i]->name, buf);
    }
    printf("\n");
    {
        char buf[64];
        format_comma_long((long)emps[max_idx].salary, buf, sizeof(buf));
        printf("Highest Paid: %s ($%s)\n", emps[max_idx].name, buf);
    }
    printf("\n");
    printf("Departments with >2 employees:\n");
    for (size_t i = 0; i < ndepts; i++) {
        if (dept_ptrs[i]->count > 2) {
            printf("  %s (%d employees)\n", dept_ptrs[i]->name, dept_ptrs[i]->count);
        }
    }
    printf("\n");
    {
        char buf[64];
        format_comma_long((long)total_budget, buf, sizeof(buf));
        printf("Total Budget: $%s\n", buf);
    }

    /* Cleanup */
    for (size_t i = 0; i < nlines; i++) free(lines[i]);
    free(lines);
    for (size_t i = 0; i < nemps; i++) {
        free(emps[i].name);
        free(emps[i].department);
    }
    free(emps);
    for (size_t i = 0; i < ndepts; i++) free(dept_names[i]);
    free(dept_names);
    free(dept_totals);
    free(dept_counts);
    free(depts);
    free(dept_ptrs);

    return 0;
}

