use std::fs;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_by_component: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: BTreeMap<u32, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || !line.starts_with('[') {
            continue;
        }

        let close_bracket = match line.find(']') {
            Some(pos) => pos,
            None => continue,
        };

        let timestamp = &line[1..close_bracket];
        let rest = line[close_bracket + 1..].trim_start();

        // Extract hour: "YYYY-MM-DD HH:MM:SS" -> hour at index 11..13
        if timestamp.len() >= 13 {
            let hour_str = &timestamp[11..13];
            if let Ok(hour) = hour_str.parse::<u32>() {
                *hour_counts.entry(hour).or_insert(0) += 1;
            }
        }

        // rest: "LEVEL (component) - message"
        let paren_pos = match rest.find(" (") {
            Some(pos) => pos,
            None => continue,
        };

        let level = &rest[..paren_pos];
        let after_paren = &rest[paren_pos + 1..];

        let close_paren = match after_paren.find(')') {
            Some(pos) => pos,
            None => continue,
        };

        let component = &after_paren[..close_paren];
        let after_close = &after_paren[close_paren + 1..];

        let message = after_close.trim_start();
        let message = if message.starts_with("- ") {
            &message[2..]
        } else if message.starts_with('-') {
            &message[1..].trim_start()
        } else {
            message
        };

        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        if level == "ERROR" {
            *error_by_component.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message.to_string());
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_component, top_count) = error_by_component
        .iter()
        .max_by_key(|(_, c)| c)
        .map(|(comp, count)| (comp.as_str(), *count))
        .unwrap_or(("N/A", 0));
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts
        .iter()
        .max_by_key(|(_, c)| c)
        .map(|(h, c)| (*h, *c))
        .unwrap_or((0, 0));
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

