import Foundation

func readJSON(_ path: String) -> Any {
    let data = try! Data(contentsOf: URL(fileURLWithPath: path))
    return try! JSONSerialization.jsonObject(with: data, options: [])
}

func canonicalJSON(_ value: Any) -> String {
    do {
        let data = try JSONSerialization.data(withJSONObject: value, options: [.sortedKeys])
        return String(data: data, encoding: .utf8)!
    } catch {
        return String(describing: value)
    }
}

func deepMerge(_ a: Any, _ b: Any) -> Any {
    if let dictA = a as? [String: Any], let dictB = b as? [String: Any] {
        var result = dictA
        for (key, value) in dictB {
            if let existing = result[key] {
                result[key] = deepMerge(existing, value)
            } else {
                result[key] = value
            }
        }
        return result
    }
    if let arrA = a as? [Any], let arrB = b as? [Any] {
        var result: [Any] = arrA
        var seen = Set(arrA.map { canonicalJSON($0) })
        for item in arrB {
            let key = canonicalJSON(item)
            if !seen.contains(key) {
                result.append(item)
                seen.insert(key)
            }
        }
        return result
    }
    return b
}

func escapeString(_ s: String) -> String {
    var result = "\""
    for char in s {
        switch char {
        case "\"": result += "\\\""
        case "\\": result += "\\\\"
        case "\n": result += "\\n"
        case "\r": result += "\\r"
        case "\t": result += "\\t"
        case "\u{08}": result += "\\b"
        case "\u{0C}": result += "\\f"
        default:
            let scalarValue = char.unicodeScalars.first!.value
            if scalarValue < 0x20 {
                result += String(format: "\\u%04x", scalarValue)
            } else {
                result += String(char)
            }
        }
    }
    result += "\""
    return result
}

func serializeJSON(_ value: Any, indent: Int) -> String {
    let prefix = String(repeating: "  ", count: indent)
    let innerPrefix = String(repeating: "  ", count: indent + 1)

    if let dict = value as? [String: Any] {
        if dict.isEmpty {
            return "{}"
        }
        let sortedKeys = dict.keys.sorted()
        let entries = sortedKeys.map { key -> String in
            let valStr = serializeJSON(dict[key]!, indent: indent + 1)
            return "\(innerPrefix)\(escapeString(key)): \(valStr)"
        }
        return "{\n" + entries.joined(separator: ",\n") + "\n\(prefix)}"
    }
    if let arr = value as? [Any] {
        if arr.isEmpty {
            return "[]"
