import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileEntry {
  relativePath: string;
  lines: number;
  chars: number;
}

function getExtension(filePath: string): string {
  return path.extname(filePath);
}

function countLines(filePath: string): number {
  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    if (content.length === 0) return 0;
    const lines = content.split('\n');
    if (lines[lines.length - 1] === '') {
      lines.pop();
    }
    return lines.length;
  } catch {
    return 0;
  }
}

function walkDir(dir: string, root: string, visited: Set<string>): FileEntry[] {
  const results: FileEntry[] = [];
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      let resolved: string;
      try {
        resolved = fs.realpathSync(fullPath);
      } catch {
        continue;
      }
      if (visited.has(resolved)) continue;
      visited.add(resolved);
      results.push(...walkDir(fullPath, root, visited));
    } else if (entry.isFile()) {
      const relPath = path.relative(root, fullPath).split(path.sep).join('/');
      const lines = countLines(fullPath);
      let chars = 0;
      try {
        chars = fs.statSync(fullPath).size;
      } catch {
        chars = 0;
      }
      results.push({ relativePath: relPath, lines, chars });
    }
  }

  return results;
}

const visited = new Set<string>();
try {
  visited.add(fs.realpathSync(rootDir));
} catch {
  visited.add(rootDir);
}

const allFiles = walkDir(rootDir, rootDir, visited);

const groups = new Map<string, FileEntry[]>();
for (const file of allFiles) {
  const ext = getExtension(file.relativePath);
  if (!groups.has(ext)) {
    groups.set(ext, []);
  }
  groups.get(ext)!.push(file);
}

const sortedExts = Array.from(groups.keys()).sort();

for (const ext of sortedExts) {
  groups.get(ext)!.sort((a, b) => a.relativePath.localeCompare(b.relativePath));
}

const output: string[] = [];
output.push('=== File Tree Analysis ===');
output.push('');

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

for (const ext of sortedExts) {
  const files = groups.get(ext)!;
  const groupLines = files.reduce((sum, f) => sum + f.lines, 0);
  const groupChars = files.reduce((sum, f) => sum + f.chars, 0);

  output.push(`Extension: ${ext}`);
  output.push(`  Files: ${files.length}`);
  output.push(`  Total Lines: ${groupLines}`);
  output.push(`  Total Characters: ${groupChars}`);

  for (const file of files) {
    output.push(`    ${file.relativePath}: ${file.lines} lines, ${file.chars} chars`);
  }

  totalFiles += files.length;
  totalLines += groupLines;
  totalChars += groupChars;
}

output.push('');
output.push(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);

process.stdout.write(output.join('\n') + '\n');

