let B: [[Int]] = [[9,8,7],[6,5,4],[3,2,1]]

func multiply(_ m1: [[Int]], _ m2: [[Int]]) -> [[Int]] {
    let rows = m1.count
    let cols = m2[0].count
    var result = Array(repeating: Array(repeating: 0, count: cols), count: rows)
    for i in 0..<rows {
        for j in 0..<cols {
            for k in 0..<m1[0].count {
                result[i][j] += m1[i][k] * m2[k][j]
            }
        }
    }
    return result
}

func determinant(_ m: [[Int]]) -> Int {
    return m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
         - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
