use std::collections::BTreeMap;
use std::io::Write;

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Json>),
    Object(BTreeMap<String, Json>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn advance(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn expect(&mut self, c: char) {
        self.skip_whitespace();
        let actual = self.advance();
        assert_eq!(actual, Some(c), "Expected '{}' but got {:?} at position {}", c, actual, self.pos);
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::String(self.parse_string()),
            Some('t') => { self.parse_literal("true"); Json::Bool(true) }
            Some('f') => { self.parse_literal("false"); Json::Bool(false) }
            Some('n') => { self.parse_literal("null"); Json::Null }
            _ => self.parse_number(),
        }
    }

    fn parse_literal(&mut self, lit: &str) {
        for c in lit.chars() {
            let actual = self.advance();
            assert_eq!(actual, Some(c), "Expected '{}' in literal", c);
        }
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.advance();
            return Json::Object(map);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_whitespace();
            match self.advance() {
                Some(',') => continue,
                Some('}') => break,
                other => panic!("Expected ',' or '}}' in object, got {:?}", other),
            }
        }
        Json::Object(map)
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.advance();
            return Json::Array(arr);
        }
        loop {
            let val = self.parse_value();
            arr.push(val);
            self.skip_whitespace();
            match self.advance() {
