use std::io::{Read, Write};
use std::net::TcpStream;

enum Json {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

fn skip_ws(s: &[u8], pos: &mut usize) {
    while *pos < s.len() && (s[*pos] == b' ' || s[*pos] == b'\t' || s[*pos] == b'\n' || s[*pos] == b'\r') {
        *pos += 1;
    }
}

fn parse_number(s: &[u8], pos: &mut usize) -> f64 {
    let start = *pos;
    if *pos < s.len() && s[*pos] == b'-' {
        *pos += 1;
    }
    while *pos < s.len() && s[*pos].is_ascii_digit() {
        *pos += 1;
    }
    if *pos < s.len() && s[*pos] == b'.' {
        *pos += 1;
        while *pos < s.len() && s[*pos].is_ascii_digit() {
            *pos += 1;
        }
    }
    if *pos < s.len() && (s[*pos] == b'e' || s[*pos] == b'E') {
        *pos += 1;
        if *pos < s.len() && (s[*pos] == b'+' || s[*pos] == b'-') {
            *pos += 1;
        }
        while *pos < s.len() && s[*pos].is_ascii_digit() {
            *pos += 1;
        }
    }
    let num_str = std::str::from_utf8(&s[start..*pos]).unwrap();
    num_str.parse::<f64>().unwrap()
}

fn parse_string(s: &[u8], pos: &mut usize) -> String {
    *pos += 1;
    let mut result = Vec::new();
    while *pos < s.len() {
        let c = s[*pos];
        if c == b'\\' {
            *pos += 1;
            let esc = s[*pos];
            match esc {
                b'"' => result.push(b'"'),
                b'\\' => result.push(b'\\'),
                b'/' => result.push(b'/'),
                b'n' => result.push(b'\n'),
                b't' => result.push(b'\t'),
                b'r' => result.push(b'\r'),
                b'b' => result.push(0x08),
                b'f' => result.push(0x0C),
                b'u' => {
                    let hex = std::str::from_utf8(&s[*pos + 1..*pos + 5]).unwrap();
                    let code = u32::from_str_radix(hex, 16).unwrap();
                    let ch = char::from_u32(code).unwrap_or('\u{FFFD}');
                    let mut buf = [0u8; 4];
                    let bytes = ch.encode_utf8(&mut buf);
                    result.extend_from_slice(bytes.as_bytes());
                    *pos += 4;
                }
                _ => result.push(esc),
            }
            *pos += 1;
        } else if c == b'"' {
            *pos += 1;
            break;
        } else {
            let byte_len = if c < 0x80 { 1 }
                else if c & 0xE0 == 0xC0 { 2 }
                else if c & 0xF0 == 0xE0 { 3 }
                else { 4 };
            result.extend_from_slice(&s[*pos..*pos + byte_len]);
            *pos += byte_len;
        }
    }
    String::from_utf8(result).unwrap()
}

fn parse_value(s: &[u8], pos: &mut usize) -> Json {
    skip_ws(s, pos);
    let c = s[*pos];
    match c {
        b'[' => {
            *pos += 1;
            skip_ws(s, pos);
            let mut arr = Vec::new();
            if *pos < s.len() && s[*pos] == b']' {
                *pos += 1;
            } else {
                loop {
                    let v = parse_value(s, pos);
                    arr.push(v);
                    skip_ws(s, pos);
                    if *pos < s.len() && s[*pos] == b',' {
                        *pos += 1;
                    } else {
                        break;
                    }
                }
            }
            if *pos < s.len() && s[*pos] == b']' {
                *pos += 1;
            }
            Json::Array(arr)
        }
        b'{' => {
            *pos += 1;
            skip_ws(s, pos);
            let mut obj = Vec::new();
            if *pos < s.len() && s[*pos] == b'}' {
                *pos += 1;
            } else {
                loop {
                    skip_ws(s, pos);
                    let key = parse_string(s, pos);
                    skip_ws(s, pos);
                    *pos += 1;
                    let val = parse_value(s, pos);
                    obj.push((key, val));
                    skip_ws(s, pos);
                    if *pos < s.len() && s[*pos] == b',' {
                        *pos += 1;
                    } else {
                        break;
                    }
                }
            }
            if *pos < s.len() && s[*pos] == b'}' {
                *pos += 1;
            }
            Json::Object(obj)
        }
        b'"' => Json::Str(parse_string(s, pos)),
        b't' => { *pos += 4; Json::Bool(true) }
        b'f' => { *pos += 5; Json::Bool(false) }
        b'n' => { *pos += 4; Json::Null }
        _ => Json::Number(parse_number(s, pos)),
    }
}

fn get_str(obj: &[(String, Json)], key: &str) -> Option<&str> {
    for (k, v) in obj {
        if k == key {
            if let Json::Str(s) = v {
                return Some(s);
            }
        }
    }
    None
}

fn get_num(obj: &[(String, Json)], key: &str) -> Option<f64> {
    for (k, v) in obj {
        if k == key {
            if let Json::Number(n) = v {
                return Some(*n);
            }
        }
    }
    None
}

fn main() {
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("Failed to connect");

    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream.write_all(request.as_bytes()).expect("Failed to write request");

    let mut buf = Vec::new();
    let mut tmp = [0u8; 4096];
    loop {
        let n = stream.read(&mut tmp).expect("Failed to read");
        if n == 0 {
            break;
        }
        buf.extend_from_slice(&tmp[..n]);
    }

    let response = String::from_utf8(buf).expect("Invalid UTF-8");
    let body_start = if let Some(idx) = response.find("\r\n\r\n") {
        idx + 4
    } else if let Some(idx) = response.find("\n\n") {
        idx + 2
    } else {
        panic!("No HTTP body separator found");
    };
    let body = &response[body_start..];
    let body_bytes = body.as_bytes();

    let mut pos = 0;
    let json = parse_value(body_bytes, &mut pos);

    let products = if let Json::Array(arr) = &json {
        arr
    } else {
        panic!("Expected JSON array");
    };

    let mut filtered: Vec<(String, f64)> = Vec::new();
    for item in products {
        if let Json::Object(obj) = item {
            let name = get_str(obj, "name").unwrap_or("").to_string();
            let price = get_num(obj, "price").unwrap_or(0.0);
            if price > 50.00 {
                filtered.push((name, price));
            }
        }
    }

    filtered.sort_by(|a, b| a.0.cmp(&b.0));

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for (name, price) in &filtered {
        println!("{}: ${:.2}", name, price);
    }
    println!();
    println!("Count: {}", filtered.len());
    let total: f64 = filtered.iter().map(|(_, p)| p).sum();
    println!("Total: ${:.2}", total);
}

