use std::fs;
use std::collections::HashMap;

enum Json {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next_char(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: char) {
        self.skip_whitespace();
        assert_eq!(self.next_char(), Some(c), "Expected '{}' at pos {}", c, self.pos);
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::Str(self.parse_string()),
            Some('t') => { self.parse_literal("true"); Json::Bool(true) }
            Some('f') => { self.parse_literal("false"); Json::Bool(false) }
            Some('n') => { self.parse_literal("null"); Json::Null }
            _ => Json::Number(self.parse_number()),
        }
    }

    fn parse_literal(&mut self, lit: &str) {
        for c in lit.chars() {
            assert_eq!(self.next_char(), Some(c));
        }
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut s = String::new();
        loop {
            match self.next_char() {
                Some('"') => break,
                Some('\\') => {
                    match self.next_char() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\u{0008}'),
                        Some('f') => s.push('\u{000C}'),
                        Some('u') => {
                            let mut code = 0u32;
                            for _ in 0..4 {
                                let c = self.next_char().unwrap();
                                code = code * 16 + (c as u32 - '0' as u32).min(9)
                                    + if c.is_ascii_alphabetic() { (c as u32 - 'a' as u32 + 10) } else { 0 };
                            }
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => {}
                    }
                }
                Some(c) => s.push(c),
                None => break,
            }
        }
        s
    }

    fn parse_number(&mut self) -> f64 {
        self.skip_whitespace();
        let mut num_str = String::new();
        if self.peek() == Some('-') {
            num_str.push('-');
            self.pos += 1;
        }
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
                // Only allow + and - after e/E
                if (c == '+' || c == '-') && num_str.len() > 0 {
                    let last = num_str.chars().last().unwrap();
                    if last != 'e' && last != 'E' {
                        break;
                    }
                }
                num_str.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        num_str.parse::<f64>().unwrap_or(0.0)
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next_char();
            return Json::Array(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_whitespace();
            match self.next_char() {
                Some(',') => continue,
                Some(']') => break,
                _ => break,
            }
        }
        Json::Array(items)
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next_char();
            return Json::Object(items);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse_value();
            items.push((key, val));
            self.skip_whitespace();
            match self.next_char() {
                Some(',') => continue,
                Some('}') => break,
                _ => break,
            }
        }
        Json::Object(items)
