                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\u{0008}'),
                        Some('f') => s.push('\u{000C}'),
                        Some('u') => {
                            let mut code = 0u32;
                            for _ in 0..4 {
                                let c = self.next_char().unwrap();
                                code = code * 16 + (c as u32 - '0' as u32).min(9)
                                    + if c.is_ascii_alphabetic() { (c as u32 - 'a' as u32 + 10) } else { 0 };
                            }
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => {}
                    }
                }
                Some(c) => s.push(c),
                None => break,
            }
        }
        s
    }

    fn parse_number(&mut self) -> f64 {
        self.skip_whitespace();
        let mut num_str = String::new();
        if self.peek() == Some('-') {
            num_str.push('-');
            self.pos += 1;
        }
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
                if (c == '+' || c == '-') && num_str.len() > 0 {
                    let last = num_str.chars().last().unwrap();
                    if last != 'e' && last != 'E' {
                        break;
                    }
                }
                num_str.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        num_str.parse::<f64>().unwrap_or(0.0)
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next_char();
            return Json::Array(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_whitespace();
            match self.next_char() {
                Some(',') => continue,
                Some(']') => break,
                _ => break,
            }
        }
        Json::Array(items)
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next_char();
            return Json::Object(items);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse_value();
            items.push((key, val));
            self.skip_whitespace();
            match self.next_char() {
                Some(',') => continue,
                Some('}') => break,
                _ => break,
            }
        }
        Json::Object(items)
    }
}

fn get_object_field<'a>(obj: &'a [(String, Json)], key: &str) -> Option<&'a Json> {
    for (k, v) in obj {
        if k == key {
            return Some(v);
        }
    }
    None
}

fn main() {
    let content = fs::read_to_string("<tmp>")
        .expect("Failed to read graph.json");

    let mut parser = Parser::new(&content);
    let json = parser.parse_value();

    let (nodes, edges) = match &json {
        Json::Object(fields) => {
            let nodes_json = get_object_field(fields, "nodes").unwrap();
            let edges_json = get_object_field(fields, "edges").unwrap();

            let nodes: Vec<String> = match nodes_json {
                Json::Array(arr) => arr.iter().map(|v| match v {
                    Json::Str(s) => s.clone(),
                    _ => String::new(),
                }).collect(),
                _ => Vec::new(),
            };

            let edges: Vec<(String, String, f64)> = match edges_json {
                Json::Array(arr) => arr.iter().filter_map(|v| {
                    if let Json::Object(efields) = v {
                        let from = get_object_field(efields, "from").and_then(|v| v.as_str()).unwrap_or("").to_string();
                        let to = get_object_field(efields, "to").and_then(|v| v.as_str()).unwrap_or("").to_string();
                        let weight = get_object_field(efields, "weight").and_then(|v| v.as_num()).unwrap_or(0.0);
                        Some((from, to, weight))
                    } else {
                        None
                    }
                }).collect(),
                _ => Vec::new(),
            };

            (nodes, edges)
        }
        _ => (Vec::new(), Vec::new()),
    };

    let mut adj: HashMap<String, Vec<(String, f64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).or_insert_with(Vec::new);
    }
    for (from, to, weight) in &edges {
        adj.entry(from.clone()).or_insert_with(Vec::new).push((to.clone(), *weight));
        adj.entry(to.clone()).or_insert_with(Vec::new).push((from.clone(), *weight));
    }

    let mut dist: HashMap<String, f64> = HashMap::new();
    let mut visited: HashMap<String, bool> = HashMap::new();

    for node in &nodes {
        dist.insert(node.clone(), f64::INFINITY);
        visited.insert(node.clone(), false);
    }
    dist.insert("A".to_string(), 0.0);

    for _ in 0..nodes.len() {
        let mut min_node: Option<String> = None;
        let mut min_dist = f64::INFINITY;
        for node in &nodes {
            if !visited[node] && dist[node] < min_dist {
                min_dist = dist[node];
                min_node = Some(node.clone());
            }
        }

        let min_node = match min_node {
            Some(n) => n,
            None => break,
        };

        if dist[&min_node] == f64::INFINITY {
            break;
        }

        visited.insert(min_node.clone(), true);

        if let Some(neighbors) = adj.get(&min_node) {
            for (neighbor, weight) in neighbors {
                let new_dist = dist[&min_node] + weight;
                if new_dist < dist[neighbor] {
                    dist.insert(neighbor.clone(), new_dist);
                }
            }
        }
    }

    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();

    for node in sorted_nodes {
        let d = dist[node];
        if d == f64::INFINITY {
            println!("A -> {}: unreachable", node);
        } else if (d - d.round()).abs() < 1e-9 {
            println!("A -> {}: {}", node, d.round() as i64);
        } else {
            println!("A -> {}: {}", node, d);
        }
    }
}

impl Json {
    fn as_str(&self) -> Option<&str> {
        match self {
            Json::Str(s) => Some(s),
            _ => None,
        }
    }

    fn as_num(&self) -> Option<f64> {
        match self {
            Json::Number(n) => Some(*n),
            _ => None,
        }
    }
}
