            Ok(t) => t,
            Err(_) => continue,
        };

        let path = entry.path();

        if ft.is_dir() {
            walk(&path, root, files);
        } else if ft.is_file() {
            let mut content = Vec::new();
            let mut file = match fs::File::open(&path) {
                Ok(f) => f,
                Err(_) => continue,
            };
            if file.read_to_end(&mut content).is_err() {
                continue;
            }

            let lines = if content.is_empty() {
