#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ftw.h>
#include <sys/stat.h>

#define ROOT "<tmp>"

typedef struct {
    char *relpath;
    char *ext;
    long lines;
    long chars;
} FileInfo;

static FileInfo *files = NULL;
static int nfiles = 0;
static int capfiles = 0;

static void add_file(const char *relpath, long lines, long chars) {
    if (nfiles >= capfiles) {
        capfiles = capfiles ? capfiles * 2 : 128;
        files = realloc(files, capfiles * sizeof(FileInfo));
        if (!files) { perror("realloc"); exit(1); }
    }
    files[nfiles].relpath = strdup(relpath);
    if (!files[nfiles].relpath) { perror("strdup"); exit(1); }

    const char *fname = strrchr(relpath, '/');
    fname = fname ? fname + 1 : relpath;
    const char *dot = strrchr(fname, '.');
    if (dot && dot != fname) {
        files[nfiles].ext = strdup(dot);
    } else {
        files[nfiles].ext = strdup("");
    }
    if (!files[nfiles].ext) { perror("strdup"); exit(1); }

    files[nfiles].lines = lines;
    files[nfiles].chars = chars;
    nfiles++;
}

static int walk_cb(const char *path, const struct stat *sb, int type, struct FTW *ftw) {
    (void)sb; (void)ftw;
    if (type != FTW_F) return 0;

    size_t rootlen = strlen(ROOT);
    if (strncmp(path, ROOT, rootlen) != 0) return 0;
    const char *rel = path + rootlen;
    if (*rel == '/') rel++;

    FILE *f = fopen(path, "rb");
    if (!f) return 0;

    long lines = 0, chars = 0;
    int c;
    while ((c = fgetc(f)) != EOF) {
        chars++;
        if (c == '\n') lines++;
    }
    fclose(f);

    add_file(rel, lines, chars);
    return 0;
}

static int cmp_files(const void *a, const void *b) {
    const FileInfo *fa = *(FileInfo *const *)a;
    const FileInfo *fb = *(FileInfo *const *)b;
    int r = strcmp(fa->ext, fb->ext);
    if (r != 0) return r;
    return strcmp(fa->relpath, fb->relpath);
}

int main(void) {
    int rc = nftw(ROOT, walk_cb, 64, FTW_PHYS);
    if (rc != 0) {
        perror("nftw");
        return 1;
    }

    qsort(files, nfiles, sizeof(FileInfo), cmp_files);

    printf("=== File Tree Analysis ===\n\n");

    long total_lines = 0, total_chars = 0;
    int i = 0;
    while (i < nfiles) {
        const char *ext = files[i].ext;
        int j = i;
        long ext_lines = 0, ext_chars = 0;
        int ext_count = 0;
        while (j < nfiles && strcmp(files[j].ext, ext) == 0) {
            ext_lines += files[j].lines;
            ext_chars += files[j].chars;
            ext_count++;
            j++;
        }

        printf("Extension: %s\n", ext);
        printf("  Files: %d\n", ext_count);
        printf("  Total Lines: %ld\n", ext_lines);
        printf("  Total Characters: %ld\n", ext_chars);
        for (int k = i; k < j; k++) {
            printf("    %s: %ld lines, %ld chars\n", files[k].relpath, files[k].lines, files[k].chars);
        }

        total_lines += ext_lines;
        total_chars += ext_chars;
        i = j;
    }

    printf("\nTotal: %d files, %ld lines, %ld characters\n", nfiles, total_lines, total_chars);

    for (int k = 0; k < nfiles; k++) {
        free(files[k].relpath);
        free(files[k].ext);
    }
    free(files);

    return 0;
}

